<script setup lang="ts">import{onMounted,ref}from'vue';import{RasterGlowTerminal}from'../src';const crt=ref<InstanceType<typeof RasterGlowTerminal>>();const text=['\x1b[1;32mRasterGlow Terminal\x1b[0m','','Windows portable + Web/Vue','ANSI · Unicode · mouse','','┌──────────────────────────────┐','│ ConPTY     CRT      Vue 3    │','├──────────────────────────────┤','│ SSH        glow     events   │','│ Vim        lines    resize   │','└──────────────────────────────┘','','Click, then type. Mouse: waiting',''];onMounted(()=>crt.value?.write('\x1b[2J\x1b[H'+text.join('\r\n')+'\r\n\x1b[92mweb@rasterglow\x1b[0m$ '));function input(d:string){const m=/\x1b\[<(\d+);(\d+);(\d+)([Mm])/.exec(d);if(m){const kind=m[1]==='35'?'MOVE':m[4]==='m'?'UP':m[1]==='64'?'WHEEL ↑':m[1]==='65'?'WHEEL ↓':'CLICK';crt.value?.write(`\x1b7\x1b[14;1H\x1b[2K\x1b[96mMouse ${kind}: C${m[2]} R${m[3]}\x1b[0m\x1b8`);return}if(d==='\r')crt.value?.write('\r\n\x1b[33mConnect @data to a PTY.\x1b[0m\r\n\x1b[92mweb@rasterglow\x1b[0m$ ');else if(d==='\x7f')crt.value?.write('\b \b');else crt.value?.write(d)}</script>
